curl -s -X POST https://slack.com/api/users.list -H "Authorization: Bearer <TOKEN>" | python3 -c "
import json,sys
data = json.load(sys.stdin)
if data.get('ok'):
    for u in data['members']:
        if 'priya' in u.get('real_name','').lower() or 'priya' in u.get('profile',{}).get('display_name','').lower():
            print(u['id'], u.get('real_name'), u.get('profile',{}).get('display_name'))
else:
    print('ERROR', data)
"

curl -s -X POST https://slack.com/api/conversations.list -H "Authorization: Bearer <TOKEN>" -d "types=public_channel,private_channel" | python3 -c "
import json,sys
data = json.load(sys.stdin)
if data.get('ok'):
    for c in data['channels']:
        if 'deploy' in c.get('name','').lower():
            print(c['id'], c.get('name'))
else:
    print('ERROR', data)
"

curl -s -X POST https://slack.com/api/search.messages -H "Authorization: Bearer <TOKEN>" -d "query=rollback from:U_PRIYA in:deploys" | python3 -c "
import json,sys
data = json.load(sys.stdin)
if data.get('ok'):
    msgs = data.get('messages',{}).get('matches',[])
    for m in msgs:
        print(m['ts'], m['user'], m['text'])
else:
    print('ERROR', data)
"
